/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: notStarted, lookupRunning, idle, luna, confirmable
 * Tests
 *   - the Luna AI controls are never primary, stop a running analysis, and say when the limit is reached or the provider failed
 *   - a failed Luna AI run is one quiet line that can be ignored while the lookup leads, saying only an unknown outcome that keeps it from starting
 *   - Use Luna AI (paid) opens an inline, non-modal confirmation focused on Cancel; Cancel and Escape start nothing and return the focus, and only its start button starts Luna AI
 *   - while the free lookup runs the confirmation warns and offers waiting, which starts nothing; once the lookup ends its labels change in place and Luna AI still waits to be started
 *   - the confirmation gives the project's runs and paid calls left and says when this is its last Luna AI run, by its runs and its paid calls left
 *   - the start button waits while Luna AI cannot run or a change is busy, and a run that starts meanwhile closes the confirmation for good
 *   - a run that starts while the focus is outside the confirmation closes it without moving the focus
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import type { CatalogReview } from './catalogReviewApi';
import { catalogReview, reviewJson, session, viewer } from './catalogReviewFixtures.testSupport';
import { pairingLookupResponse, pairingReview } from './catalogReviewLookupFixtures.testSupport';
import type { ReviewLookupResponse } from './catalogReviewLookupApi';
import { CatalogReviewLuna, lunaRunsLeft } from './CatalogReviewLuna';
import styles from './adminStyles';

/**
 * The Luna AI controls of an unapplied Album completion on their own: status, Use Luna AI (paid) and Stop, their notes, and the
 * inline confirmation with its concurrent-lookup warning, live labels and last-run line. Lookup reads are answered per path; every
 * name and identifier is synthetic.
 */
const notStarted = (): ReviewLookupResponse => ({ lookup: null, revision: 1, valueRevision: 0, summary: { waiting: { lookup: false, analysis: false }, needsAnswer: { tie: false, conflicts: [] }, lookupAvailable: true, primaryArtists: [] } });
/** The review's lookup still running (no candidates yet). */
const lookupRunning = (): ReviewLookupResponse => {
  const response = pairingLookupResponse();
  Object.assign(response.lookup!, { state: 'running', outcome: null, candidates: [], groups: [], applied: null, preselection: null, needsAnswer: { tie: false, conflicts: [] } });
  response.summary.waiting.lookup = true; return response;
};
const idle = (item: CatalogReview): CatalogReview => ({ ...item, analysis: { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }, suggestions: [] });
beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

/** The Luna AI controls on their own, beside a review whose lookup reads `lookup`. */
function luna(item: CatalogReview, lookup: () => ReviewLookupResponse = notStarted) {
  vi.stubGlobal('fetch', vi.fn(async (path: string) => path.endsWith('/lookup') ? reviewJson(lookup()) : reviewJson({ code: 'unexpected' }, 500)));
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const element = (value: CatalogReview) => <QueryClientProvider client={client}><CatalogReviewLuna item={value} active={false} canAnalyze={false} onAnalyze={() => undefined}
    onStop={() => undefined} busy={false} /></QueryClientProvider>;
  return { ...render(element(item)), element };
}

test('the Luna AI controls are never primary, stop a running analysis, and say when the limit is reached or the provider failed', () => {
  const onAnalyze = vi.fn(), onStop = vi.fn(), item = catalogReview();
  const client = new QueryClient(); client.setQueryData(['browser-session'], session);
  const view = render(<CatalogReviewLuna item={item} active={false} canAnalyze onAnalyze={onAnalyze} onStop={onStop} busy={false} />,
    { wrapper: ({ children }) => <QueryClientProvider client={client}>{children}</QueryClientProvider> });
  const again = screen.getByRole('button', { name: 'Use Luna AI again (paid)' });
  expect(again).not.toHaveClass(styles.primary);
  // It opens its confirmation; only the confirmation's start button starts Luna AI.
  fireEvent.click(again); expect(onAnalyze).not.toHaveBeenCalled();
  fireEvent.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Start Luna AI analysis (paid)' })); expect(onAnalyze).toHaveBeenCalledTimes(1);
  view.rerender(<CatalogReviewLuna item={{ ...item, analysis: { ...item.analysis, state: 'running' } }} active canAnalyze={false} onAnalyze={onAnalyze} onStop={onStop} busy={false} />);
  const stop = screen.getByRole('button', { name: 'Stop Luna AI' });
  expect(stop).not.toHaveClass(styles.primary);
  fireEvent.click(stop); expect(onStop).toHaveBeenCalledTimes(1);
  expect(screen.getByRole('status')).toHaveTextContent(/Luna AI/);
  view.rerender(<CatalogReviewLuna item={{ ...item, analysis: { ...item.analysis, state: 'needsAttention', generation: 2, issue: 'providerInvalidResponse' } }} active={false} canAnalyze={false}
    onAnalyze={onAnalyze} onStop={onStop} busy={false} />);
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).toBeDisabled();
  expect(screen.getByText(/limit/i)).toBeVisible();
  expect(screen.getByRole('status')).toHaveTextContent(/\S/);
  // Without a lookup that leads, a failed run reads calmly beside its reason, never as needing attention.
  expect(screen.getByText('Last run did not succeed')).toBeVisible();
  expect(screen.queryByText(/needs attention/i)).not.toBeInTheDocument();
});

test('a failed Luna AI run is one quiet line that can be ignored while the lookup leads, saying only an unknown outcome that keeps it from starting', async () => {
  const failed = (item: CatalogReview, issue: CatalogReview['analysis']['issue']) => ({ ...item, analysis: { ...item.analysis, state: 'needsAttention' as const, generation: 1, issue } });
  const quiet = 'Luna AI (paid, optional): the last run did not succeed; you can ignore it.';
  // The lookup found a possible release that needs numbers: the failed run is one quiet line, its reason left out.
  const { rerender, element } = luna(failed(pairingReview(), 'providerInvalidResponse'), pairingLookupResponse);
  expect(await screen.findByText(quiet)).toBeVisible();
  expect(screen.queryByText(/could not be validated/)).not.toBeInTheDocument();
  expect(screen.queryByRole('status')).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).not.toHaveClass(styles.primary);
  // An unknown outcome keeps Luna AI from starting, so it is said, muted.
  rerender(element(failed(pairingReview(), 'providerOutcomeUnknown')));
  expect(screen.getByText(quiet)).toBeVisible();
  expect(screen.getByRole('status')).toHaveClass(styles.muted);
  cleanup();
  // A lookup that found nothing to use leaves the run's reason in view.
  luna(failed(pairingReview(), 'providerInvalidResponse'), () => { const response = pairingLookupResponse(); Object.assign(response.lookup!, { candidates: [], outcome: 'noRelease' }); return response; });
  expect(await screen.findByRole('status')).toHaveTextContent(/\S/);
  expect(screen.getByText('Last run did not succeed')).toBeVisible();
  expect(screen.queryByText(quiet)).not.toBeInTheDocument();
});

/** The controls able to start Luna AI beside a review whose lookup reads `lookup()` on each read; `client` re-reads it. */
function confirmable(item: CatalogReview, lookup: () => ReviewLookupResponse, props: { canAnalyze?: boolean; busy?: boolean } = {}) {
  const fetch = vi.fn(async (path: string) => path.endsWith('/lookup') ? reviewJson(lookup()) : reviewJson({ code: 'unexpected' }, 500));
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const onAnalyze = vi.fn(), onStop = vi.fn();
  const element = (value: CatalogReview, next = props) => <QueryClientProvider client={client}><CatalogReviewLuna item={value} active={['queued', 'running'].includes(value.analysis.state)} canAnalyze={next.canAnalyze ?? true}
    busy={next.busy ?? false} onAnalyze={onAnalyze} onStop={onStop} /></QueryClientProvider>;
  const view = render(element(item));
  return { client, fetch, onAnalyze, rerender: (value: CatalogReview, next = props) => view.rerender(element(value, next)),
    dialog: () => screen.getByRole('dialog', { name: 'Use Luna AI? This is a paid AI service' }) };
}

test('Use Luna AI (paid) opens an inline, non-modal confirmation focused on Cancel; Cancel and Escape start nothing and return the focus, and only its start button starts Luna AI', async () => {
  const { onAnalyze, dialog, fetch } = confirmable(idle(pairingReview()), () => pairingLookupResponse());
  await act(async () => { await Promise.resolve(); });
  const open = screen.getByRole('button', { name: 'Use Luna AI (paid)' });
  expect(open).not.toHaveClass(styles.primary); expect(open).toHaveAttribute('aria-expanded', 'false');
  fireEvent.click(open);
  expect(dialog()).toHaveAttribute('aria-modal', 'false');
  expect(dialog()).toHaveAccessibleDescription(/paid AI service/);
  expect(open).toHaveAttribute('aria-expanded', 'true');
  // No warning while the lookup has ended; the safe choice takes the focus.
  expect(within(dialog()).queryByRole('note')).not.toBeInTheDocument();
  expect(within(dialog()).getByRole('button', { name: 'Cancel' })).toHaveFocus();
  fireEvent.click(within(dialog()).getByRole('button', { name: 'Cancel' }));
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(open).toHaveFocus();
  fireEvent.click(open);
  fireEvent.keyDown(within(dialog()).getByRole('button', { name: 'Cancel' }), { key: 'Escape' });
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(onAnalyze).not.toHaveBeenCalled();
  fireEvent.click(open);
  fireEvent.click(within(dialog()).getByRole('button', { name: 'Start Luna AI analysis (paid)' }));
  expect(onAnalyze).toHaveBeenCalledOnce();
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  // The controls only read the lookup; starting is the caller's.
  expect(fetch.mock.calls.every(([path]) => String(path).endsWith('/lookup'))).toBe(true);
});

test('while the free lookup runs the confirmation warns and offers waiting, which starts nothing; once the lookup ends its labels change in place and Luna AI still waits to be started', async () => {
  let response = lookupRunning();
  const { client, onAnalyze, dialog } = confirmable(idle(pairingReview()), () => response);
  fireEvent.click(screen.getByRole('button', { name: 'Use Luna AI (paid)' }));
  const note = await within(dialog()).findByRole('note');
  expect(note).toHaveTextContent('Free metadata lookup is still running');
  expect(note).toHaveTextContent(/both will run at the same time/);
  const wait = within(dialog()).getByRole('button', { name: 'Wait for free results' }), start = within(dialog()).getByRole('button', { name: 'Start Luna AI anyway (paid)' });
  expect(start).toHaveClass(styles.primary);
  // Waiting only closes the confirmation: nothing starts and the lookup is left running.
  fireEvent.click(wait);
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(onAnalyze).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Use Luna AI (paid)' }));
  const safe = within(dialog()).getByRole('button', { name: 'Wait for free results' });
  expect(safe).toHaveFocus();
  // The lookup ends while the confirmation is open: the warning goes, the same buttons change their labels and keep the focus.
  response = pairingLookupResponse();
  await act(async () => { await client.invalidateQueries(); });
  await waitFor(() => expect(within(dialog()).queryByRole('note')).not.toBeInTheDocument());
  expect(safe).toHaveAccessibleName('Cancel'); expect(safe).toHaveFocus();
  expect(within(dialog()).getByRole('button', { name: 'Start Luna AI analysis (paid)' })).toBeEnabled();
  expect(screen.queryByRole('button', { name: /anyway/ })).not.toBeInTheDocument();
  // Luna AI never starts by itself.
  await act(async () => { await new Promise(resolve => setTimeout(resolve, 50)); });
  expect(onAnalyze).not.toHaveBeenCalled();
  fireEvent.click(within(dialog()).getByRole('button', { name: 'Start Luna AI analysis (paid)' }));
  expect(onAnalyze).toHaveBeenCalledOnce();
});

test('the confirmation gives the project\'s runs and paid calls left and says when this is its last Luna AI run, by its runs and its paid calls left', async () => {
  const last = 'This is the project\'s last Luna AI analysis.';
  // One run used of two: the last.
  const used = catalogReview();
  expect(lunaRunsLeft(used)).toBe(1);
  const { dialog, rerender } = confirmable(used, notStarted);
  fireEvent.click(screen.getByRole('button', { name: 'Use Luna AI again (paid)' }));
  expect(within(dialog()).getByText(last)).toBeVisible();
  const budget = (item: CatalogReview) => `Left for this project: ${2 - item.analysis.generation} Luna AI runs and ${item.analysis.maxAttempts - item.analysis.attemptsUsed} paid AI calls.`;
  expect(within(dialog()).getByText(budget(used))).toBeVisible();
  // No run used: two left, so it says nothing of a last run.
  const fresh = idle(catalogReview());
  expect(lunaRunsLeft(fresh)).toBe(2);
  rerender(fresh);
  expect(within(dialog()).queryByText(last)).not.toBeInTheDocument();
  expect(within(dialog()).getByText(budget(fresh))).toBeVisible();
  // Paid calls left that cover one more run (one for the Album and one per ten tracks) make it the last too, as none left makes none.
  const calls = { ...fresh, analysis: { ...fresh.analysis, attemptsUsed: fresh.analysis.maxAttempts - 3 } };
  expect(lunaRunsLeft(calls)).toBe(1);
  rerender(calls);
  expect(within(dialog()).getByText(last)).toBeVisible();
  expect(lunaRunsLeft({ ...fresh, analysis: { ...fresh.analysis, attemptsUsed: fresh.analysis.maxAttempts } })).toBe(0);
  expect(lunaRunsLeft({ ...fresh, analysis: { ...fresh.analysis, generation: 2 } })).toBe(0);
});

test('the start button waits while Luna AI cannot run or a change is busy, and a run that starts meanwhile closes the confirmation for good', async () => {
  const item = idle(catalogReview()), { dialog, rerender, onAnalyze } = confirmable(item, notStarted);
  fireEvent.click(screen.getByRole('button', { name: 'Use Luna AI (paid)' }));
  rerender(item, { canAnalyze: false });
  expect(within(dialog()).getByRole('button', { name: 'Start Luna AI analysis (paid)' })).toBeDisabled();
  rerender(item, { canAnalyze: true, busy: true });
  expect(within(dialog()).getByRole('button', { name: 'Start Luna AI analysis (paid)' })).toBeDisabled();
  rerender(item, { canAnalyze: true });
  expect(within(dialog()).getByRole('button', { name: 'Start Luna AI analysis (paid)' })).toBeEnabled();
  // A run started elsewhere (another tab) closes it; nothing was started here, and the focus it held goes to Stop Luna AI.
  expect(within(dialog()).getByRole('button', { name: 'Cancel' })).toHaveFocus();
  rerender({ ...item, analysis: { ...item.analysis, state: 'running' } });
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  const stop = screen.getByRole('button', { name: 'Stop Luna AI' });
  expect(stop).toHaveFocus();
  // When that run ends the confirmation stays closed and takes no focus: nobody opened it again.
  const elsewhere = document.createElement('button'); document.body.append(elsewhere); elsewhere.focus();
  rerender({ ...item, analysis: { ...item.analysis, state: 'complete', generation: 1 } });
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).toHaveAttribute('aria-expanded', 'false');
  expect(elsewhere).toHaveFocus();
  elsewhere.remove();
  expect(onAnalyze).not.toHaveBeenCalled();
});

test('a run that starts while the focus is outside the confirmation closes it without moving the focus', () => {
  const item = idle(catalogReview()), { rerender } = confirmable(item, notStarted);
  fireEvent.click(screen.getByRole('button', { name: 'Use Luna AI (paid)' }));
  const elsewhere = document.createElement('button'); document.body.append(elsewhere);
  elsewhere.focus();
  rerender({ ...item, analysis: { ...item.analysis, state: 'running' } });
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(elsewhere).toHaveFocus();
  rerender({ ...item, analysis: { ...item.analysis, state: 'complete', generation: 1 } });
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(elsewhere).toHaveFocus();
  elsewhere.remove();
});
